import time
from ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions import DataTransferUePcServerException
from ta_ue_plugin_qualcomm.ue.qualcomm.pc_server.server_commands import THROUGHPUT


class UePcServerRunner(object):
    """Ue Pc Server Runner"""

    def __init__(self, ue_name, dt_name, dt_protocol, dt_direction, ue_pc_instance, ue_id, ue_ip, ue_type, command_tail,
                 app_srv_lte_ip=None, ue_iperf_adb_dir=None, iperf_version=None, analyzer_params=None,
                 verification_delay=10, local_timestamp=None):
        """
        :param ue_name:
        :param dt_name:
        :param dt_protocol:
        :param dt_direction:
        :param ue_pc_instance:
        :param ue_id:
        :param ue_ip:
        :param ue_type:
        :param command_tail:
        :param app_srv_lte_ip:
        :param ue_iperf_adb_dir:
        :param iperf_version:
        :param analyzer_params:
        """
        self.running = False
        self.ue_pc_instance = ue_pc_instance
        self.ue_name = ue_name
        self.data_transfer_name = dt_name
        self.data_transfer_protocol = dt_protocol
        self.data_transfer_direction = dt_direction
        self.ue_id = ue_id
        self.ue_type = ue_type
        self.command_tail = command_tail
        self.ue_ip = ue_ip
        self.lte_network_ip = app_srv_lte_ip
        self.ue_iperf_adb_dir = ue_iperf_adb_dir
        self.analyzer_params = analyzer_params
        self.iperf_version = iperf_version
        self.verification_delay = verification_delay
        self.log_path = None
        self.local_timestamp = local_timestamp if local_timestamp else time.strftime("%H_%M_%S", time.localtime())

    def start(self):
        """
        Starts the throughput on UePcServer
        :raises ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions.pyDataTransferUePcServerException if tput start failed
        """
        status, metadata = self.ue_pc_instance.send(THROUGHPUT.START,
                                                    alias=self.ue_name,
                                                    throughput_alias=self.data_transfer_name,
                                                    ue_type=self.ue_type,
                                                    ue_id=self.ue_id,
                                                    data_transfer_direction=self.data_transfer_direction,
                                                    data_transfer_type=self.data_transfer_protocol,
                                                    command_parameters=self.command_tail,
                                                    app_server_lte_ip=self.lte_network_ip,
                                                    ue_ip=self.ue_ip,
                                                    iperf_path=self.ue_iperf_adb_dir,
                                                    analyzer_params=self.analyzer_params,
                                                    iperf_version=self.iperf_version,
                                                    skip_n_first_messages=self.verification_delay,
                                                    local_timestamp=self.local_timestamp)
        if status:
            self.running = True
        else:
            raise DataTransferUePcServerException("Failed starting data transfer: %s" % metadata)

    def stop(self):
        """
        Stops the throughput on UePcServer
        :raises ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions.pyDataTransferUePcServerException if tput stop failed
        """
        status, metadata = self.ue_pc_instance.send(THROUGHPUT.STOP,
                                                    alias=self.ue_name,
                                                    throughput_alias=self.data_transfer_name)
        if status or "Iperf was closed on Ue before STOP was called due to unknown cause" in metadata:
            self.running = False
        else:
            raise DataTransferUePcServerException("Failed stopping data transfer: %s" % metadata)

    def is_running(self):
        """
        Check if data UePcSrv is running

        :return: boolean
        """
        return self.running

    def get_statistics(self):
        """
        Returns dictionary with traffic stats

        :return: dict
        :raises ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions.pyDataTransferUePcServerException if get statistics failed
        """
        status, metadata = self.ue_pc_instance.send(THROUGHPUT.GET_STATISTICS,
                                                    alias=self.ue_name,
                                                    throughput_alias=self.data_transfer_name)
        if status:
            return metadata
        else:
            raise DataTransferUePcServerException("Failed getting data transfer statistics: %s" % metadata)

    def reset_statistics(self):
        """
        Clears stats
        :raises ta_ue_plugin_qualcomm.ue.qualcomm.qc_ue_exceptions.pyDataTransferUePcServerException if reset statistics failed
        """
        status, metadata = self.ue_pc_instance.send(THROUGHPUT.RESET_STATISTICS,
                                                    alias=self.ue_name,
                                                    throughput_alias=self.data_transfer_name)
        if not status:
            raise DataTransferUePcServerException("Failed resetting data transfer statistics: %s" % metadata)
